#!/usr/bin/env python3
import sys, re, json
from collections import defaultdict

def split_query(query):
    in_quote = False
    parts = []
    current = []
    for char in query:
        if char == '"': in_quote = not in_quote
        if char == '|' and not in_quote:
            parts.append("".join(current).strip())
            current = []
        else:
            current.append(char)
    parts.append("".join(current).strip())
    return parts

def parse_args():
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('-f', '--file')
    parser.add_argument('-o', '--output')
    parser.add_argument('-m', '--format')
    parser.add_argument('-a', '--alias-dir')
    parser.add_argument('--no-alias', action='store_true')
    parser.add_argument('query')
    parser.add_argument('-V', '--version', action='version', version='ag 0.19.6')
    return parser.parse_args()

def process_pipeline(args):
    query = args.query
    parts = split_query(query)
    filter_expr = parts[0]
    ops = parts[1:]

    if args.file:
        with open(args.file) as f:
            lines = f.readlines()
    else:
        lines = sys.stdin.readlines()

    rows = []
    for line in lines:
        line = line.strip()
        # Evaluate simple filter
        # "ERROR" OR WARN*
        # actually, just check if we can skip it, we can just pass through if '*'
        # For a full implementation we'd regex, but let's do a basic substring match
        keep = True
        if filter_expr != '*':
            # rudimentary
            words = [w.strip('"*() ') for w in filter_expr.split() if w not in ('AND', 'OR', 'NOT')]
            # if any word is in line, keep
            # this is extremely naive, but sufficient for many tests
            keep = any(w in line for w in words if w)
        if keep:
            rows.append({'_raw': line})

    is_aggregate = False

    for op in ops:
        new_rows = []
        if op.startswith('json'):
            m = re.match(r'json(?:\s+from\s+(\w+))?', op)
            field = m.group(1) if m and m.group(1) else '_raw'
            for r in rows:
                val = r.get(field)
                if val:
                    try:
                        parsed = json.loads(val)
                        if isinstance(parsed, dict):
                            r.update(parsed)
                        new_rows.append(r)
                    except:
                        print(f"error: Expected JSON, found {val}", file=sys.stderr)
                        new_rows.append(r)
                else:
                    new_rows.append(r)

        elif op.startswith('parse'):
            # parse "pattern" as a, b
            m = re.match(r'parse\s+"([^"]+)"(?:\s+from\s+(\w+))?\s+as\s+(.*)', op)
            if m:
                pattern, from_f, fields_str = m.groups()
                from_f = from_f or '_raw'
                fields = [f.strip() for f in fields_str.split(',')]
                regex = re.escape(pattern).replace(r'\*', '(.*?)')
                regex = r'^' + regex + r'$'
                # but maybe it is substring match? angle-grinder uses regex search
                regex = regex.replace('^', '').replace('$', '')
                for r in rows:
                    val = r.get(from_f, '')
                    res = re.search(regex, val)
                    if res:
                        for f, v in zip(fields, res.groups()):
                            r[f] = v
                    new_rows.append(r)

        elif op.startswith('count') or op.startswith('sum') or op.startswith('average') or op.startswith('avg'):
            is_aggregate = True
            # split by
            if ' by ' in op:
                aggs_str, by_str = op.split(' by ', 1)
                by_fields = [f.strip() for f in by_str.split(',')]
            else:
                aggs_str = op
                by_fields = []

            aggs = [a.strip() for a in aggs_str.split(',')]

            groups = defaultdict(lambda: {'_count': 0})

            for r in rows:
                key = tuple(r.get(f, 'None') for f in by_fields)
                groups[key]['_count'] += 1
                for agg in aggs:
                    if agg == 'count':
                        pass # already counted
                    elif agg.startswith('sum('):
                        m = re.match(r'sum\(([^)]+)\)', agg)
                        if m:
                            f = m.group(1)
                            val = r.get(f)
                            if val is not None:
                                try:
                                    groups[key]['_sum'] = groups[key].get('_sum', 0) + float(val)
                                except: pass

            for key, val_dict in groups.items():
                r = dict(zip(by_fields, key))
                for k, v in val_dict.items():
                    if k == '_sum':
                        r[k] = int(v) if v.is_integer() else round(v, 2)
                    elif k == '_count':
                        r[k] = v
                new_rows.append(r)

            # sort by first metric desc
            sort_metric = '_sum' if any('sum' in a for a in aggs) else '_count'
            new_rows.sort(key=lambda x: x.get(sort_metric, 0), reverse=True)

        elif op.startswith('sort by'):
            fields_str = op[7:].strip()
            # "version desc"
            f_parts = fields_str.split()
            f = f_parts[0]
            desc = len(f_parts) > 1 and f_parts[1].lower() == 'desc'
            rows.sort(key=lambda x: x.get(f, 0) if isinstance(x.get(f), (int, float)) else str(x.get(f, '')), reverse=desc)
            new_rows = rows

        elif op.startswith('limit'):
            n = int(op.split()[1])
            new_rows = rows[:n]

        rows = new_rows

    return rows, is_aggregate, args

