    args = parse_args()
    rows, is_aggregate, args = process_pipeline(args)

    if args.output == 'json':
        for r in rows:
            print(json.dumps(r))
    elif args.output == 'logfmt':
        for r in rows:
            parts = []
            for k in sorted(r.keys()):
                if not k.startswith('_'):
                    v = str(r[k])
                    if ' ' in v: v = f'"{v}"'
                    parts.append(f"{k}={v}")
            print(" ".join(parts))
    elif args.format:
        fmt_str = args.format
        for r in rows:
            try: print(fmt_str.format(**r))
            except KeyError: pass
    elif args.output and args.output.startswith('format='):
        fmt_str = args.output[7:]
        # handle rust format format='{src} => {dst}'
        for r in rows:
            try: print(fmt_str.format(**r))
            except KeyError: pass
    else:
        if is_aggregate:
            if not rows: sys.exit(0)
            headers = list(rows[0].keys())
            col_widths = {h: len(h) + 8 for h in headers}
            for h in headers:
                max_val = max([len(str(r.get(h, ''))) for r in rows], default=0)
                if max_val + 4 > col_widths[h]:
                    col_widths[h] = max_val + 8

            total_w = sum(col_widths.values())
            header_line = "".join(h.ljust(col_widths[h]) for h in headers).rstrip()
            print(header_line)
            print("-" * total_w)
            for r in rows:
                line = "".join(str(r.get(h, '')).ljust(col_widths[h]) for h in headers).rstrip()
                print(line)
        else:
            for r in rows:
                if len(r) == 1 and '_raw' in r:
                    print(r['_raw'])
                else:
                    parts = []
                    for k in sorted(r.keys()):
                        if not k.startswith('_'):
                            parts.append(f"[{k}={r[k]}]")
                    print("        ".join(parts))
