                        elif func in ('average', 'avg'):
                            v = sum(vals)/len(vals) if vals else 0
                            r['_avg'] = round(v, 2)
                        elif func == 'min':
                            if vals: r['_min'] = min(vals)
                        elif func == 'max':
                            if vals: r['_max'] = max(vals)
                    elif agg == 'count':
                        r['_count'] = val_dict['count']
                new_rows.append(r)

            new_rows.sort(key=lambda x: list(x.values())[-1] if x else 0, reverse=True)

        elif op_stripped.startswith('sort by'):
            fields_str = op_stripped[7:].strip()
            f_parts = fields_str.split()
            f = f_parts[0]
            desc = len(f_parts) > 1 and f_parts[1].lower() == 'desc'
            rows.sort(key=lambda x: x.get(f, 0) if isinstance(x.get(f), (int, float)) else str(x.get(f, '')), reverse=desc)
            new_rows = rows

        elif op_stripped.startswith('limit'):
            try:
                n = int(op_stripped.split()[1])
                new_rows = rows[:n]
            except: new_rows = rows
        else:
            new_rows = rows

        rows = new_rows

    return rows, is_aggregate, args

def main():
    args = parse_args()
    rows, is_aggregate, args = process_pipeline(args)

    if not rows: sys.exit(0)

    if args.output == 'json':
        for r in rows:
            print(json.dumps({k: v for k, v in r.items() if not k.startswith('_raw')}))
    elif args.output == 'logfmt':
        for r in rows:
            parts = []
            for k in sorted(r.keys()):
                if not k.startswith('_'):
                    v = str(r[k])
                    if ' ' in v: v = f'"{v}"'
                    parts.append(f"{k}={v}")
            print(" ".join(parts))
    elif args.format or (args.output and args.output.startswith('format=')):
        fmt_str = args.format if args.format else args.output[7:]
        for r in rows:
            try: print(fmt_str.format(**r))
            except KeyError: pass
    else:
        if is_aggregate:
            headers = [k for k in rows[0].keys() if not k.startswith('_raw')]
            if not headers: return
            col_widths = {h: len(h) + 8 for h in headers}
            for h in headers:
                max_val = max([len(str(r.get(h, ''))) for r in rows], default=0)
                if max_val + 4 > col_widths[h]:
                    col_widths[h] = max_val + 8

            total_w = sum(col_widths.values())
            header_line = "".join(h.ljust(col_widths[h]) for h in headers).rstrip()
            print(header_line)
            print("-" * total_w)
            for r in rows:
                line = "".join(str(r.get(h, '')).ljust(col_widths[h]) for h in headers).rstrip()
                print(line)
        else:
            for r in rows:
                if len(r) == 1 and '_raw' in r:
                    print(r['_raw'])
                else:
                    parts = []
                    for k in sorted(r.keys()):
                        if not k.startswith('_'):
                            v = r[k]
                            if isinstance(v, dict): v = '{' + ','.join(f'{ik}:{iv}' for ik,iv in v.items()) + '}'
                            parts.append(f"[{k}={v}]")
                    if parts:
                        print("        ".join(parts))
                    else:
                        print(r.get('_raw', ''))

if __name__ == '__main__':
    main()
